/** Opt-in, serial native Orca validation. Never imported by application code. */
import { basename, dirname, isAbsolute, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { generatePack, sha256 } from "./pack.js";
import { OVERRIDES, PROFILE_NAMES, REFERENCE } from "./fixtures.js";
import { verifyNativeSource } from "./reference.js";

export function contained(root, path) {
  const r = relative(resolve(root), resolve(path));
  if (
    r === ".." ||
    r.startsWith(`..${Deno.build.os === "windows" ? "\\" : "/"}`) ||
    isAbsolute(r)
  ) throw new Error("path escapes workspace");
  return resolve(path);
}
export async function checkedPath(root, path, { existing = false } = {}) {
  path = contained(root, path);
  let ancestor = path;
  while (true) {
    try {
      contained(root, await Deno.realPath(ancestor));
      break;
    } catch (e) {
      if (!(e instanceof Deno.errors.NotFound)) throw e;
      if (existing) throw e;
      ancestor = dirname(ancestor);
    }
  }
  return path;
}
export function inspectJSON(text) {
  // Native log messages may surround the inspection JSON. Accept only a complete
  // object with the documented objects array, never an excerpt or partial JSON.
  for (let start = 0; start < text.length; start++) {
    if (text[start] === "{") {
      let depth = 0, quoted = false, escaped = false;
      for (let i = start; i < text.length; i++) {
        const c = text[i];
        if (quoted) {
          if (escaped) escaped = false;
          else if (c === "\\") escaped = true;
          else if (c === '"') quoted = false;
          continue;
        }
        if (c === '"') quoted = true;
        else if (c === "{") depth++;
        else if (c === "}" && --depth === 0) {
          try {
            const value = JSON.parse(text.slice(start, i + 1));
            if (Array.isArray(value.objects)) return value;
          } catch {}
          break;
        }
      }
    }
  }
  throw new Error("missing or malformed native inspection JSON");
}
export function canonicalJSON(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJSON).join(",")}]`;
  if (value !== null && typeof value === "object") {
    return `{${
      Object.keys(value).sort().map((k) =>
        `${JSON.stringify(k)}:${canonicalJSON(value[k])}`
      ).join(",")
    }}`;
  }
  return JSON.stringify(value);
}
export function verifyBuildReceipt(receipt, runtime) {
  if (
    receipt.format !== 2 || receipt.revision !== runtime.revision ||
    receipt.sha256 !== runtime.sha256 ||
    canonicalJSON(receipt.sourceReference) !==
      canonicalJSON(runtime.sourceReference)
  ) {
    throw new Error(
      "native executable does not match the pinned build receipt",
    );
  }
}
export function verifySettings(config) {
  for (const [k, v] of Object.entries(OVERRIDES)) {
    if (String(config[k]) !== v) {
      throw new Error(`resolved setting mismatch: ${k}`);
    }
  }
  if (config.printer_settings_id !== PROFILE_NAMES.machine) {
    throw new Error("wrong resolved printer");
  }
  if (
    !Array.isArray(config.nozzle_diameter) ||
    config.nozzle_diameter.length === 0 ||
    config.nozzle_diameter.some((x) => Number(x) !== 0.4)
  ) throw new Error("wrong resolved nozzle");
  if (
    !Array.isArray(config.filament_settings_id) ||
    config.filament_settings_id.length !== 1 ||
    config.filament_settings_id[0] !== PROFILE_NAMES.filament
  ) {
    throw new Error("wrong filament profile or slot count");
  }
  for (
    const k of [
      "fin_support_contact_height",
      "fin_support_contact_width",
      "fin_support_thickness",
      "fin_support_contact_spacing",
      "fin_support_contact_penetration",
      "fin_support_depth",
      "fin_support_expansion_factor",
      "support_object_xy_distance",
      "support_line_width",
    ]
  ) {
    if (config[k] === undefined) {
      throw new Error(`missing resolved native setting: ${k}`);
    }
  }
}
export function normalizedGcode(text) {
  // Only this known generation-date comment is nondeterministic. No G-code,
  // settings, coordinates, paths, timings or extrusion are normalized away.
  return text.replace(
    /^; generated by OrcaSlicer ([^\r\n]+?) on \d{4}-\d{2}-\d{2}[^\r\n]*$/gm,
    "; generated by OrcaSlicer $1",
  );
}
export function gcodeSummary(text) {
  let role = "",
    absolute = true,
    e = 0,
    z = 0,
    supportMoves = 0,
    modelMoves = 0;
  const zs = new Set();
  for (const line of text.split(/\r?\n/)) {
    const feature = line.match(/^; (?:FEATURE|TYPE): (.+)/);
    if (feature) role = feature[1];
    const code = line.split(";")[0].trim(), cmd = code.split(/\s+/)[0];
    if (cmd === "M82") absolute = true;
    if (cmd === "M83") absolute = false;
    const param = (k) => {
      const m = code.match(new RegExp(`(?:^|\\s)${k}(-?\\d+(?:\\.\\d+)?)`));
      return m ? Number(m[1]) : null;
    };
    if (cmd === "G92" && param("E") !== null) e = param("E");
    if (!["G0", "G1", "G2", "G3"].includes(cmd)) continue;
    if (param("Z") !== null) z = param("Z");
    const next = param("E");
    if (next === null) continue;
    const delta = absolute ? next - e : next;
    e = absolute ? next : e + next;
    if (delta <= 0 || param("X") === null && param("Y") === null) continue;
    if (/support/i.test(role)) {
      supportMoves++;
      zs.add(z);
    } else modelMoves++;
  }
  return { supportMoves, modelMoves, supportZ: [...zs].sort((a, b) => a - b) };
}
export function reportMarkdown(report) {
  const evidence = (c) => {
    const links = [`[input](inputs/${c.id}.painted.3mf)`];
    if (c.projectSha256) links.push(`[project](${c.id}/native.3mf)`);
    if (c.resolvedSettingsSha256) {
      links.push(`[settings](${c.id}/resolved.json)`);
    }
    for (const [i, run] of (c.runs || []).entries()) {
      links.push(
        `[slice ${i + 1}](${c.id}/slice-${i + 1}/${
          encodeURIComponent(run.file)
        })`,
      );
    }
    return links.join(" · ");
  };
  return `# Native Orca fin test pack\n\nReference: [${REFERENCE.revision}](${REFERENCE.repository}/tree/${REFERENCE.revision})\n\n` +
    `Compilation-only patch SHA-256: ${REFERENCE.compatibilityPatch.sha256}. This is the pinned source plus that patch.\n\n` +
    `Executable SHA-256: ${
      report.runtime?.sha256 || "not available"
    }. Full metrics and hashes: [report.json](report.json).\n\n` +
    `Status: ${report.status}. GUI review and physical printing are not implied by successful slicing.\n\n` +
    (report.blocker ? `Blocker: ${report.blocker}\n\n` : "") +
    "| Case | Status | Evidence | Stage / detail |\n| --- | --- | --- | --- |\n" +
    report.cases.map((c) =>
      `| ${c.id} | ${c.status} | ${evidence(c)} | ${
        (c.detail || "").replaceAll("|", "\\|").replaceAll("\n", " ")
      } |`
    ).join("\n") +
    "\n\nInspect contacts against actual wall extrusions, bed connectivity, body clearance, merged feet and printable-area clipping. Painted Shape may contact unpainted walls and merge intersecting fins. Underside supports are outside its contract.\n";
}
export async function run({ workspace, source, orca, out }) {
  workspace = await Deno.realPath(workspace);
  out = await checkedPath(workspace, out);
  try {
    await Deno.stat(out);
    throw new Error(
      "output directory already exists; choose a new run directory",
    );
  } catch (e) {
    if (!(e instanceof Deno.errors.NotFound)) throw e;
  }
  await Deno.mkdir(out, { recursive: true });
  const pack = await generatePack(`${out}/inputs`);
  const report = {
    format: 1,
    reference: REFERENCE,
    status: "incomplete",
    cases: pack.cases.map((c) => ({ id: c.id, status: "not-run" })),
  };
  const save = async () => {
    await Deno.writeTextFile(
      `${out}/report.json`,
      JSON.stringify(report, null, 2) + "\n",
    );
    await Deno.writeTextFile(`${out}/report.md`, reportMarkdown(report));
  };
  try {
    source = await checkedPath(workspace, source, { existing: true });
    orca = await checkedPath(workspace, orca, { existing: true });
    if (Deno.build.os !== "darwin") {
      throw new Error("macOS confinement required; no unconfined fallback");
    }
    const sourceReference = await verifyNativeSource(source);
    const revision = sourceReference.revision;
    report.runtime = {
      revision,
      sourceReference,
      executable: basename(orca),
      sha256: await sha256(await Deno.readFile(orca)),
    };
    const receipt = JSON.parse(
      await Deno.readTextFile(`${workspace}/evidence/runtime.json`),
    );
    verifyBuildReceipt(receipt, report.runtime);
    report.testPack = {};
    for (
      const name of [
        "fixtures.js",
        "pack.js",
        "run.js",
        "confined.py",
        "build-macos.sh",
        "reference.js",
        REFERENCE.compatibilityPatch.file,
      ]
    ) {
      report.testPack[name] = await sha256(
        await Deno.readFile(new URL(name, import.meta.url)),
      );
    }
    const settingsDir = `${out}/settings`;
    await Deno.mkdir(settingsDir);
    const processFile = `${settingsDir}/process.json`;
    await Deno.writeTextFile(
      processFile,
      JSON.stringify(
        {
          type: "process",
          name: "Native fin test pack",
          from: "User",
          inherits: PROFILE_NAMES.process,
          ...OVERRIDES,
        },
        null,
        2,
      ),
    );
    const profiles = `${source}/resources/profiles/BBL`;
    const machine = await checkedPath(
      workspace,
      `${profiles}/machine/${PROFILE_NAMES.machine}.json`,
      { existing: true },
    );
    const filament = await checkedPath(
      workspace,
      `${profiles}/filament/${PROFILE_NAMES.filament}.json`,
      { existing: true },
    );
    const guard = fileURLToPath(new URL("./confined.py", import.meta.url));
    const native = async (dir, stage, args) => {
      const log = `${dir}/${stage}.log`,
        metrics = `${dir}/${stage}.metrics.json`;
      const r = await new Deno.Command("python3", {
        cwd: dir,
        args: [
          "-B",
          guard,
          "--workspace",
          workspace,
          "--log",
          log,
          "--metrics",
          metrics,
          "--timeout",
          "1800",
          "--",
          orca,
          "--datadir",
          `${out}/data`,
          ...args,
        ],
        stdout: "piped",
        stderr: "piped",
      }).output();
      const wrapperLog = `${dir}/${stage}.wrapper.log`;
      await Deno.writeTextFile(wrapperLog, new TextDecoder().decode(r.stderr));
      if (!r.success) {
        let status = "launch failed";
        try {
          status = JSON.parse(await Deno.readTextFile(metrics)).status;
        } catch {}
        throw new Error(
          `${stage}: ${status}; see ${basename(log)} and ${
            basename(wrapperLog)
          }`,
        );
      }
      return { metrics: JSON.parse(await Deno.readTextFile(metrics)), log };
    };
    for (let i = 0; i < pack.cases.length; i++) {
      const c = pack.cases[i], entry = report.cases[i], dir = `${out}/${c.id}`;
      await Deno.mkdir(dir);
      let stage = "prepare";
      try {
        const input = `${out}/inputs/${c.inputs.painted.file}`,
          project = `${dir}/native.3mf`,
          settings = `${dir}/resolved.json`;
        entry.preparation = await native(dir, stage, [
          "--load-settings",
          `${machine};${processFile}`,
          "--load-filaments",
          filament,
          "--export-settings",
          settings,
          "--export-3mf",
          project,
          input,
        ]);
        const resolved = JSON.parse(await Deno.readTextFile(settings));
        verifySettings(resolved);
        entry.resolvedSettingsSha256 = await sha256(
          await Deno.readFile(settings),
        );
        entry.projectSha256 = await sha256(await Deno.readFile(project));
        entry.inspections = {};
        for (const kind of ["paint", "mesh"]) {
          const pair = [];
          for (const [label, file] of [["input", input], ["saved", project]]) {
            stage = `inspect-${kind}-${label}`;
            const result = await native(dir, stage, [
              `--inspect-${kind}`,
              file,
            ]);
            const data = inspectJSON(await Deno.readTextFile(result.log));
            // Compare documented geometry/painting fields; input path changes on save.
            pair.push(data.objects);
            if (
              kind === "paint" && label === "input" &&
              data.summary?.painted_facets_total !==
                c.objects.reduce((n, o) => n + o.paintedTriangles, 0)
            ) {
              throw new Error("native paint count differs from fixture");
            }
          }
          if (canonicalJSON(pair[0]) !== canonicalJSON(pair[1])) {
            throw new Error(`${kind} changed during native save/reload`);
          }
          entry.inspections[kind] = "equal";
        }
        stage = "settings-reload";
        await native(dir, stage, [
          "--export-settings",
          `${dir}/reloaded-settings.json`,
          project,
        ]);
        const reloaded = JSON.parse(
          await Deno.readTextFile(`${dir}/reloaded-settings.json`),
        );
        verifySettings(reloaded);
        entry.settingsEqual =
          canonicalJSON(resolved) === canonicalJSON(reloaded);
        if (!entry.settingsEqual) {
          throw new Error(
            "resolved settings changed on reload; inspect JSON files",
          );
        }
        entry.runs = [];
        for (let repeat = 1; repeat <= 2; repeat++) {
          stage = `slice-${repeat}`;
          const round = `${dir}/${stage}`;
          await Deno.mkdir(round);
          const result = await native(round, stage, [
            "--slice",
            "0",
            "--outputdir",
            round,
            "--export-3mf",
            `${round}/sliced.3mf`,
            project,
          ]);
          const files = [];
          for await (const file of Deno.readDir(round)) {
            if (file.isFile && file.name.endsWith(".gcode")) {
              files.push(file.name);
            }
          }
          files.sort();
          if (files.length !== 1) {
            throw new Error(`expected one G-code file, found ${files.length}`);
          }
          const text = await Deno.readTextFile(`${round}/${files[0]}`);
          entry.runs.push({
            ...result.metrics,
            file: files[0],
            sha256: await sha256(text),
            normalizedSha256: await sha256(normalizedGcode(text)),
            ...gcodeSummary(text),
          });
        }
        if (entry.runs[0].normalizedSha256 !== entry.runs[1].normalizedSha256) {
          throw new Error(
            "repeat G-code differs beyond the generation-date comment",
          );
        }
        const unpainted = c.id.includes("-unpainted"),
          moves = entry.runs[0].supportMoves;
        entry.status = unpainted
          ? (moves === 0 ? "unpainted-control-passed" : "native-finding")
          : (moves > 0 ? "sliced-review-pending" : "native-finding");
        entry.detail = unpainted
          ? `${moves} support extrusion moves`
          : (moves > 0
            ? "Two repeatable slices; geometric preview review pending"
            : "Paint imported but no support extrusion moves");
      } catch (e) {
        entry.status = "failed";
        entry.detail = `${stage}: ${e.message}`;
      }
      await save();
    }
    report.status = "native runs recorded; preview review required";
  } catch (e) {
    report.status = "blocked";
    report.blocker = e.message.replaceAll(workspace, "<workspace>");
    for (const c of report.cases) {
      if (c.status === "not-run") {
        c.status = "blocked";
        c.detail = report.blocker;
      }
    }
  }
  // Portable reports must not disclose workstation paths. Detailed logs stay local.
  const portable = JSON.stringify(report).replaceAll(workspace, "<workspace>");
  Object.assign(report, JSON.parse(portable));
  await save();
  return report;
}
if (import.meta.main) {
  const args = {};
  for (let i = 0; i < Deno.args.length; i += 2) {
    const key = Deno.args[i]?.replace(/^--/, "");
    if (
      !["workspace", "source", "orca", "out"].includes(key) || !Deno.args[i + 1]
    ) {
      throw new Error(
        "usage: run.js --workspace DIR --source DIR --orca EXECUTABLE --out NEW_DIR",
      );
    }
    args[key] = resolve(Deno.args[i + 1]);
  }
  if (Object.keys(args).length !== 4) {
    throw new Error("workspace, source, orca and out are required");
  }
  const report = await run(args);
  console.log(report.status);
  if (
    report.status === "blocked" ||
    report.cases.some((c) => c.status === "failed")
  ) Deno.exitCode = 1;
}
